+      const response = await fetch(`/api/review/requests/${encodeURIComponent(id)}/rejection`, {
+        method: "POST",
+        headers: { "Content-Type": "application/json" },
+        body: JSON.stringify({ retry: true }),
+      });
+      if (response.ok) setState({ status: "missing" });
+    } finally {
+      setPending(false);
+    }
+  }
+
+  return (
+    <section className="min-h-0 p-4 lg:overflow-y-auto">
+      {id && (
+        <Button className="mb-4 lg:hidden" type="button" variant="ghost" render={<Link href="/review" />}>
+          <ArrowLeftIcon /> Back to requests
+        </Button>
+      )}
+      {state.status === "loading" && (
+        <div className="flex items-center gap-2 text-muted-foreground">
+          <Spinner /> Loading request
+        </div>
+      )}
+      {state.status === "unselected" && (
+        <p className="text-muted-foreground">Select a signup request to review its details.</p>
+      )}
+      {state.status === "missing" && (
+        <p className="text-muted-foreground">This signup request is no longer available for review.</p>
+      )}
+      {state.status === "ready" && (
+        <div className="flex flex-col gap-5">
+          {state.request.status === "rejection_pending_notification" ? (
+            <Alert variant="destructive">
+              <CircleAlertIcon />
+              <AlertTitle>Rejection notification needs retrying</AlertTitle>
+              <AlertDescription>
+                The rejection was recorded, but we could not capture the applicant&apos;s notification.
+              </AlertDescription>
+              <AlertAction>
+                <Button disabled={pending} onClick={() => void retryNotification()} size="sm" type="button">
+                  {pending && <Spinner data-icon="inline-start" />}
+                  Retry notification
+                </Button>
+              </AlertAction>
+            </Alert>
+          ) : (
+            <>
+              <dl className="grid gap-5 sm:grid-cols-2">
+                <div>
+                  <dt className="font-medium">Name</dt>
+                  <dd>
+                    {state.request.givenName} {state.request.familyName}
+                  </dd>
+                </div>
+                <div>
+                  <dt className="font-medium">Contact email</dt>
+                  <dd className="break-all">{state.request.contactEmail}</dd>
+                </div>
+                <div>
+                  <dt className="font-medium">Phone</dt>
+                  <dd>{state.request.phone ?? "Not provided"}</dd>
+                </div>
+                <div>
+                  <dt className="font-medium">Submitted</dt>
+                  <dd>{new Date(state.request.createdAt).toLocaleDateString()}</dd>
+                </div>
+                <div className="sm:col-span-2">
+                  <dt className="font-medium">Connection to the nonprofit</dt>
+                  <dd className="whitespace-pre-wrap">{state.request.connection ?? "Not provided"}</dd>
+                </div>
+              </dl>
+              <Separator />
+              {!editing && !rejecting && (
+                <div className="flex flex-wrap gap-2">
+                  <Button onClick={() => setEditing(true)} type="button" variant="outline">
+                    <PencilIcon data-icon="inline-start" /> Correct details
+                  </Button>
+                  <Button onClick={() => setRejecting(true)} type="button" variant="destructive">
+                    Reject request
+                  </Button>
+                </div>
+              )}
+              {editing && (
+                <form noValidate onSubmit={correct}>
+                  <FieldSet disabled={pending}>
+                    <FieldGroup>
+                      <Field>
+                        <FieldLabel htmlFor="given-name">Given name</FieldLabel>
+                        <Input defaultValue={state.request.givenName} id="given-name" name="givenName" required />
+                        <FieldError>{errors.givenName}</FieldError>
+                      </Field>
+                      <Field>
+                        <FieldLabel htmlFor="family-name">Family name</FieldLabel>
+                        <Input defaultValue={state.request.familyName} id="family-name" name="familyName" required />
+                        <FieldError>{errors.familyName}</FieldError>
+                      </Field>
+                      <Field data-invalid={Boolean(errors.contactEmail)}>
+                        <FieldLabel htmlFor="contact-email">Contact email</FieldLabel>
+                        <Input
+                          aria-invalid={Boolean(errors.contactEmail)}
+                          defaultValue={state.request.contactEmail}
+                          id="contact-email"
+                          name="contactEmail"
+                          required
+                          type="email"
+                        />
+                        <FieldError>{errors.contactEmail}</FieldError>
+                      </Field>
+                      <Field orientation="horizontal">
+                        <Checkbox
+                          defaultChecked={state.request.contactEmailConfirmedByAdmin}
+                          id="contact-email-confirmed"
+                          name="contactEmailConfirmedByAdmin"
+                        />
+                        <FieldLabel htmlFor="contact-email-confirmed">
+                          I confirm this contact email as an administrator.
+                        </FieldLabel>
+                      </Field>
+                      <Field>
+                        <FieldLabel htmlFor="phone">Phone number</FieldLabel>
+                        <Input defaultValue={state.request.phone ?? ""} id="phone" name="phone" type="tel" />
+                        <FieldError>{errors.phone}</FieldError>
+                      </Field>
+                      <Field>
+                        <FieldLabel htmlFor="connection">Connection to the nonprofit</FieldLabel>
+                        <Textarea defaultValue={state.request.connection ?? ""} id="connection" name="connection" />
+                        <FieldError>{errors.connection}</FieldError>
+                      </Field>
+                      <div className="flex flex-wrap gap-2">
+                        <Button type="submit">{pending && <Spinner data-icon="inline-start" />}Save corrections</Button>
+                        <Button onClick={() => setEditing(false)} type="button" variant="outline">
+                          Cancel
+                        </Button>
+                      </div>
+                    </FieldGroup>
+                  </FieldSet>
+                </form>
+              )}
+              {rejecting && (
+                <form noValidate onSubmit={reject}>
+                  <FieldSet disabled={pending}>
+                    <FieldGroup>
+                      <Field data-invalid={Boolean(errors.reason)}>
+                        <FieldLabel htmlFor="rejection-reason">Reason for the applicant</FieldLabel>
+                        <Textarea aria-invalid={Boolean(errors.reason)} id="rejection-reason" name="reason" required />
+                        <FieldError>{errors.reason}</FieldError>
+                      </Field>
+                      <div className="flex flex-wrap gap-2">
+                        <Button type="submit" variant="destructive">
+                          {pending && <Spinner data-icon="inline-start" />}Reject and notify applicant
+                        </Button>
+                        <Button onClick={() => setRejecting(false)} type="button" variant="outline">
+                          Cancel
+                        </Button>
+                      </div>
+                    </FieldGroup>
+                  </FieldSet>
+                </form>
+              )}
+            </>
+          )}
+        </div>
+      )}
+      {state.status !== "loading" &&
+        state.status !== "ready" &&
+        state.status !== "missing" &&
+        state.status !== "unselected" && <ReviewAccess outcome={state.status} retry={() => void retry()} />}
+    </section>
+  );
+}

