                          id="connection"
                          name="connection"
                        />
                        <FieldError>{errors.connection}</FieldError>
                      </Field>
                      <div className="flex flex-wrap gap-2">
                        <Button type="submit">
                          {pending && <Spinner data-icon="inline-start" />}Save corrections
                        </Button>
                        <Button onClick={() => setEditing(false)} type="button" variant="outline">
                          Cancel
                        </Button>
                      </div>
